use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_in_set_a(c: char) -> bool {
    c == 'A' || c == 'E' || c == 'F' || c == 'H' || c == 'I' || 
    c == 'K' || c == 'L' || c == 'M' || c == 'N' || c == 'T' || 
    c == 'V' || c == 'W' || c == 'X' || c == 'Y' || c == 'Z'
}

spec fn is_in_set_b(c: char) -> bool {
    c == 'B' || c == 'C' || c == 'D' || c == 'G' || c == 'J' || 
    c == 'O' || c == 'P' || c == 'Q' || c == 'R' || c == 'S' || 
    c == 'U'
}

spec fn all_in_set_a(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i && i < s.len() ==> is_in_set_a(s[i])
}

spec fn all_in_set_b(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i && i < s.len() ==> is_in_set_b(s[i])
}

spec fn all_in_same_set(s: Seq<char>) -> bool {
    all_in_set_a(s) || all_in_set_b(s)
}

fn solve(word: Vec<char>) -> (result: Vec<char>)
    requires
        1 <= word.len() <= 10,
        forall|i: int| 0 <= i && i < word.len() ==> 
            'A' as u8 <= word[i] as u8 <= 'Z' as u8,
    ensures
        (result@ == new_strlit("YES")@ || result@ == new_strlit("NO")@),
        (result@ == new_strlit("YES")@) == all_in_same_set(word@),
{
    let mut i: usize = 0;
    let mut all_a: bool = true;
    let mut all_b: bool = true;
    
    // Check each character to determine if they're all in the same set
    while i < word.len()
        invariant
            0 <= i <= word.len(),
            all_a == (forall|j: int| 0 <= j && j < i ==> is_in_set_a(word@[j])),
            all_b == (forall|j: int| 0 <= j && j < i ==> is_in_set_b(word@[j])),
        decreases word.len() - i,
    {
        let c = word[i];
        
        // Check if character is in Set A
        let in_a = is_in_set_a(c);
        // Check if character is in Set B
        let in_b = is_in_set_b(c);
        
        // Update flags based on current character
        if !in_a {
            all_a = false;
        }
        if !in_b {
            all_b = false;
        }
        
        i = i + 1;
    }
    
    // Determine result based on flags
    if all_a || all_b {
        // All characters are in the same set
        let yes_str = new_strlit("YES");
        result = yes_str.into_bytes();
    } else {
        // Characters are mixed between sets
        let no_str = new_strlit("NO");
        result = no_str.into_bytes();
    }
    
    result
}

}